import React, { useState } from "react";

const EmployeePage = ({ vehicleRegistration, ownerName, ownerPhone, managerName }) => {
  const [selectedRole, setSelectedRole] = useState("driver");
  const employees = {
    driver: [
      {
        id: 1,
        name: "John Doe",
        phone: "1234567890",
        fixedSalary: "20000",
        expense: "5000",
        earnedMoney: "15000",
        remainingAmount: "10000",
        daysWorked: 20,
      },
    ],
    driller: [],
    manager: [],
    worker: [],
  };

  const handleRoleClick = (role) => {
    setSelectedRole(role);
  };

  return (
    <div className="employee-page">
      <header className="header-bar">
        <div className="registration">Vehicle Registration: {vehicleRegistration}</div>
        <div className="owner-info">
          Owner: {ownerName} | Phone: {ownerPhone}
        </div>
        <div className="manager-info">Manager: {managerName}</div>
      </header>

      <div className="content">
        <aside className="roles">
          <ul>
            {Object.keys(employees).map((role) => (
              <li
                key={role}
                className={selectedRole === role ? "active" : ""}
                onClick={() => handleRoleClick(role)}
              >
                {role.charAt(0).toUpperCase() + role.slice(1)}
              </li>
            ))}
          </ul>
        </aside>

        <main className="employee-cards">
          {employees[selectedRole].length > 0 ? (
            employees[selectedRole].map((employee) => (
              <div className="card" key={employee.id}>
                <h3>{employee.name}</h3>
                <p>Phone: {employee.phone}</p>
                <p>Fixed Salary: ₹{employee.fixedSalary}</p>
                <hr />
                <p>Expense: ₹{employee.expense}</p>
                <p>Earned Money: ₹{employee.earnedMoney}</p>
                <p>Remaining Amount: ₹{employee.remainingAmount}</p>
                <p>Days Worked: {employee.daysWorked}</p>
              </div>
            ))
          ) : (
            <p>No employees found for this role.</p>
          )}
        </main>
      </div>
    </div>
  );
};

export default EmployeePage;
